{
  "observed_defect": "Northern prairie lacks natural, camera-visible relief; flat terrain with no gentle valleys or broad slopes; no meaningful ground contact or asymmetry; no visible connection to existing cliffs or city pad; no terrain seams or joins visible; no sculpt-",
  "design_intent": "Introduce one broad, asymmetrical gentle hill with a central valley, connected to existing cliffs via a natural slope; ensure camera-visible change with clear ground contact and terrain continuity; preserve all existing assets and boundaries; avoid rigid waves",
  "asset_decision": "MODIFY",
  "reason_for_new_geometry": "Required for natural prairie relief; no new assets needed; existing mesh can be modified to match reference",
  "planned_actions": [
    {
      "id": "hill_1",
      "type": "sculpt_region",
      "target": "ZoneOne continuous prairie source",
      "rationale": "Create broad, asymmetrical hill with central valley",
      "parameters": {
        "center": [-50, 54, 0.4071593],
        "delta": [0, 0, 4.0],
        "radius": 30
      }
    },
    {
      "id": "valley_1",
      "type": "sculpt_path",
      "target": "ZoneOne continuous prairie source",
      "rationale": "Create central valley connecting to existing cliffs",
      "parameters": {
        "knots": [
          {
            "center": [-50, 54, 0.4071593],
            "delta": [0, 0, -2.0],
            "radius": 10
          },
          {
            "center": [-4, 54, 0.4682583],
            "delta": [0, 0, -2.0],
            "radius": 10
          }
        ]
      }
    }
  ],
  "expected_visual_difference": "Camera-visible change: one broad, asymmetrical hill with a central valley; natural terrain joins; ground contact; no rigid waves or mountains",
  "mobile_risks": "Low; no new assets or complex geometry; only sculpt operations; no risk of deformation or lost source integrity"
}
